// My leagues: which leagues show up.
import {S} from '../state.js';
import {esc,pageHead,scoring} from '../core.js';

export function settings(){return pageHead('My leagues','One account. Every team you care about.',S.serviceMode?'':`<button class="primary" data-connect>${S.data.demo?'Connect Sleeper':'Switch account'}</button>`)+`<div class="panel"><div class="section-bar"><div><h2 style="margin-bottom:6px">${S.data.demo?'Explore three sample leagues':esc(S.data.user.username)}</h2><p class="muted small">Choose which leagues appear in your watchroom and analysis.</p></div><span class="pill ${S.data.demo?'demo':'live'}">${S.data.demo?'SAMPLE DATA':'CONNECTED'}</span></div>${S.data.leagues.map((l,i)=>`<label class="league-settings"><input type="checkbox" data-league-toggle="${esc(l.league_id)}" ${l.enabled?'checked':''} ${l.inactive?'disabled':''}><div style="flex:1"><strong>${esc(l.name)}</strong><div class="muted small">${l.inactive?`${esc(l.inactive)} · `:''}${scoring(l)} · ${l.rosters.length} teams · ${l.settings?.type===2?'Dynasty':l.settings?.type===1?'Keeper':'Redraft'}</div></div>${!S.data.demo?`<a href="https://sleeper.com/leagues/${esc(l.league_id)}" target="_blank" rel="noopener" class="link-external">Open ↗</a>`:''}</label>`).join('')}</div><div class="split"><div class="panel"><h3>Made for game day</h3><p class="muted small">Pin players for quick scanning. Use Focus mode for a larger watchroom. Include opponents to spot players who help one team and hurt another.</p></div><div class="panel"><h3>About your data</h3><p class="muted small">Public Sleeper data is read-only. Scores refresh every 45 seconds while this tab is visible; they may trail the broadcast. NFL game status comes from ESPN. Projections are cached for one hour, trends for 15 minutes, and player details for 24 hours. Saved data survives page reloads. Refresh bypasses score and projection caches; Refresh outlook reloads future weeks.</p></div></div><div class="panel"><h3>Prototype limits</h3><p class="muted small">Projection access is experimental and can change. Advice uses expected points, not a calibrated win probability. Advanced bonuses, dynasty values, FAAB bids are not yet included. External notifications require the optional background service. Trade estimates use future weekly projections and replacement value, not trade-market prices. “Unavailable” never means zero.</p></div>${S.serviceMode?'<p class="muted small">This account is set where Awaker is installed, with SLEEPER_USERNAME.</p>':!S.data.demo?'<button class="secondary disconnect" id="disconnect">Disconnect and return to demo</button>':''}`;}
